<script setup lang="ts">
import { reviewTerm, reviewModelName, reviewLimitation } from '@/utils/reviewPresentation'
import { computed, nextTick, ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import { participationRuns, readableModelFields, sceneTrackRows } from '@/utils/activityAnalysis'
import type { ActivityFrame, ActivityParticipant } from '@/types/lessonReview'
import AppIcon from '@/components/common/AppIcon.vue'
import LessonStudentState from './LessonStudentState.vue'
import { studentStateColor, studentStateName } from '@/utils/studentStates'
import { overallEngagement, engagementSummary } from '@/utils/classEngagement'

const store = useLessonReviewStore()
const heatmapMode = ref<'states' | 'scores'>('states')
const hasVisualReference = computed(() => frames.value.some(frame => frame.visual_reference !== undefined))
const stateHeatmap = computed(() => hasVisualReference.value && heatmapMode.value === 'states')
const stateCodes: Record<string, string> = { read: '读', write: '写', lookup: '抬', turn_head: '转', raise_hand: '举', stand: '站', discuss: '讨', head_up: '姿', head_lowered: '姿', hand_near_head: '姿', standing: '姿', unknown: '—' }
function cellLabel(cell: ActivityParticipant | null) { return cell?.student_state?.label || cell?.label || 'unknown' }
function cellText(cell: ActivityParticipant | null) { return stateHeatmap.value ? stateCodes[cellLabel(cell)] || '—' : cell?.score === null || !cell ? '—' : cell.score.toFixed(2) }
function cellTitle(cell: ActivityParticipant | null) { return cell ? `${studentStateName(cellLabel(cell))} · 状态置信度 ${percentage(cell.student_state?.confidence ?? cell.confidence)} · ${stateHeatmap.value ? '可见状态，不是积极度分数' : `时序规则分数 ${cell.score ?? '未知'}`}` : '未观测' }
const tabs = [{ id: 'overview', label: '学生状态与积极度' }, { id: 'heatmap', label: '对象热图' }, { id: 'frames', label: '原始帧证据' }, { id: 'models', label: '模型与边界' }] as const
const selectedScene = ref<number | null>(null)
const framePage = ref(0)
const failedImages = ref(new Set<string>())
const analysis = computed(() => store.data?.activity_analysis)
const frames = computed(() => analysis.value?.frames || [])
const currentFrame = computed(() => store.currentActivityFrame)
const currentContexts = computed(() => analysis.value?.context_segments.filter(row => row.start_sec <= store.currentTime && store.currentTime < row.end_sec) || [])
const scenes = computed(() => [...new Set(frames.value.map(frame => frame.scene_id))])
const sceneId = computed(() => selectedScene.value ?? currentFrame.value?.scene_id ?? scenes.value[0])
const sceneFrames = computed(() => frames.value.filter(frame => frame.scene_id === sceneId.value))
const heatmapStart = ref(0)
const trackContainer = ref<HTMLDivElement | null>(null)
const heatmapFrames = computed(() => sceneFrames.value.slice(heatmapStart.value, heatmapStart.value + 100))
const trackRows = computed(() => sceneId.value === undefined ? [] : sceneTrackRows(heatmapFrames.value, sceneId.value))
const sourceFrames = computed(() => frames.value.slice(framePage.value * 12, (framePage.value + 1) * 12))
const overallScores = computed(() => overallEngagement(frames.value))
const classSummary = computed(() => engagementSummary(frames.value, overallScores.value))
const curveFrames = computed(() => frames.value.map((frame, index) => ({ ...frame, participation_index: frame.visual_reference ? overallScores.value[index]!.smoothed_index : frame.participation ? (frame.participation.active_fraction === null ? null : frame.participation.active_fraction * 100) : frame.participation_index })))
const curveRuns = computed(() => participationRuns(curveFrames.value))
const modelFields = computed(() => readableModelFields(analysis.value?.models || {}))
const summaryCoverage = computed(() => analysis.value?.summary.person_observations ? analysis.value.summary.known_observations / analysis.value.summary.person_observations : null)
const behaviors = computed(() => {
  const counts: Record<string, number> = {}
  for (const frame of frames.value) for (const [label, count] of Object.entries(frame.behaviors)) counts[label] = (counts[label] || 0) + count
  return Object.entries(counts).sort((a, b) => b[1] - a[1])
})
const maxBehavior = computed(() => Math.max(1, ...behaviors.value.map(row => row[1])))
const timelineGroups = [
  { id: 'actions', label: '模型读写与举手', labels: ['read', 'write', 'raise_hand'], color: '#275cc2' },
  { id: 'lookup', label: '模型抬头', labels: ['lookup'], color: '#5a88d5' },
  { id: 'other', label: '模型转头站立讨论', labels: ['turn_head', 'stand', 'discuss'], color: '#8cafe3' },
  { id: 'pose', label: '几何姿态', labels: ['head_up', 'head_lowered', 'hand_near_head', 'standing'], color: '#c0d4ee' },
  { id: 'unknown', label: '状态未知', labels: ['unknown'], color: '#e3ebf6' },
]
const stateTimelines = computed(() => frames.value.map(frame => {
  const counts = frame.student_state_counts || {}
  const segments = timelineGroups.map(group => ({ ...group, count: group.labels.reduce((n, label) => n + (counts[label] || 0), 0) }))
  return { frame, segments, title: `${formatReviewTime(frame.timestamp_sec)} · ${frame.detected_people} 个检测对象 · ${segments.map(group => `${group.label} ${group.count}`).join(' / ')}` }
}))
const names: Record<string, string> = { reading: '阅读', writing: '书写', listening: '听讲', hand_raising: '举手', raising_hand: '举手', raise_hand: '举手', standing: '站立', discussion: '讨论', unknown: '未知', looking_forward: '面向前方', head_down: '低头', sleeping: '伏桌', using_phone: '使用手机', no_people: '未检测到可见对象', low_evidence: '行为证据不足', observed: '已观测' }
const detectorNames: Record<string, string> = { read: '阅读', write: '书写', lookup: '抬头线索', turn_head: '转头线索', stand: '站立线索', discuss: '讨论线索' }
const name = (label: string) => detectorNames[label] || names[label] || label
const percentage = (value: number | null) => value === null ? '未知' : `${(value * 100).toFixed(1)}%`
const frameCoverage = (frame: ActivityFrame) => !frame.detected_people ? '未知（无可用检测）' : percentage(frame.coverage)
const x = (frame: ActivityFrame) => 44 + frame.timestamp_sec / Math.max(1, store.duration) * 850
const y = (frame: ActivityFrame) => 142 - (frame.participation_index ?? 0) * 1.2
const points = (run: ActivityFrame[]) => run.map(frame => `${x(frame)},${y(frame)}`).join(' ')
const cellStyle = (cell: ActivityParticipant | null) => stateHeatmap.value ? cell && cellLabel(cell) !== 'unknown' ? { backgroundColor: studentStateColor(cellLabel(cell)), color: ['raise_hand', 'discuss', 'stand'].includes(cellLabel(cell)) ? '#fff' : '#173b70' } : {} : cell?.score === null || !cell ? {} : { backgroundColor: `rgba(36, 94, 219, ${.15 + cell.score * .8})`, color: cell.score > .5 ? '#fff' : '#244b85' }
function seekFrame(frame: ActivityFrame) { selectedScene.value = null; store.seek(frame.timestamp_sec) }
function imageFailed(id: string) { failedImages.value = new Set([...failedImages.value, id]) }
watch(() => store.data?.lesson.id, () => { selectedScene.value = null; framePage.value = 0; heatmapStart.value = 0; failedImages.value = new Set() })
watch(sceneId, () => { heatmapStart.value = 0 })
watch([() => currentFrame.value?.id, sceneId], async () => {
  const frame = currentFrame.value
  if (!frame || frame.scene_id !== sceneId.value) return
  const index = sceneFrames.value.findIndex(row => row.id === frame.id)
  if (index < 0) return
  heatmapStart.value = Math.floor(index / 100) * 100
  await nextTick()
  const container = trackContainer.value
  const header = container && [...container.querySelectorAll<HTMLElement>('th[data-frame-id]')].find(el => el.dataset.frameId === frame.id)
  if (container && header) container.scrollLeft += header.getBoundingClientRect().left - container.getBoundingClientRect().left - container.clientWidth / 2
})
</script>

<template>
  <section id="behavior" class="panel lesson-behavior">
    <div class="panel-heading"><div><h2>学生行为分析</h2><p>原录像时间 · 可见对象观测 · 行为证据</p></div><span class="tag" :class="{ sand: !analysis }">{{ analysis ? '同源行为分析' : '未提供' }}</span></div>
    <div v-if="!analysis" class="behavior-empty"><AppIcon name="chart" :size="30" /><div><strong>本课未提供同源的行为分析</strong><p>当前没有可核验的行为曲线或对象轨迹。未知时段保留为空，不能解释为零参与。</p></div></div>
    <template v-else>
      <div class="behavior-body"><div v-if="hasVisualReference" class="dense-method-note"><span>七类模型候选</span><div><strong>整图与切片联合检测</strong><p v-if="currentFrame?.detection_review">当前保留 {{ currentFrame.detected_people }} 个人物候选框<span v-if="currentFrame.detection_review.previous_detected_people !== undefined">，原结果为 {{ currentFrame.detection_review.previous_detected_people }} 个</span>。镜面候选按配置排除，检测数量不等于全班人数或召回率。</p><p>本课的七类候选尚未人工标注验收。整体积极度按原项目七类权重汇总，评分覆盖率单独提示，当前仍为模型估计。</p></div></div>
        <div class="behavior-tabs" role="tablist" aria-label="行为分析视图"><button v-for="tab in tabs" :id="`behavior-${tab.id}-tab`" :key="tab.id" role="tab" :aria-selected="store.behaviorView === tab.id" :aria-controls="`behavior-${tab.id}-panel`" :class="{ active: store.behaviorView === tab.id }" @click="store.behaviorView = tab.id">{{ tab.label }}</button></div>
        <div :id="`behavior-${store.behaviorView}-panel`" role="tabpanel" :aria-labelledby="`behavior-${store.behaviorView}-tab`">
        <div v-if="store.behaviorView === 'overview'" class="current-student-panel" data-behavior-panel="overview"><LessonStudentState :frame="currentFrame" /></div>

        <div v-if="store.behaviorView === 'overview' && hasVisualReference" class="behavior-block" data-testid="visible-state-timeline"><div class="block-title"><h3>可见状态随时间变化</h3><small>逐帧构成 · 点击回看</small></div><p class="block-note">按当前检测对象展示模型候选、几何姿态和未知。无人物的镜头保留空白；构成比例不是全班比例或心理积极度。</p><div class="state-timeline" aria-label="可见状态构成与原录像时间"><button v-for="row in stateTimelines" :key="row.frame.id" :title="row.title" :aria-label="row.title" :class="{ current: row.frame.id === currentFrame?.id, missing: !row.frame.detected_people }" :style="{ width: `${(row.frame.end_sec - row.frame.start_sec) / store.duration * 100}%` }" @click="seekFrame(row.frame)"><i v-for="segment in row.segments" :key="segment.id" :style="{ height: `${row.frame.detected_people ? segment.count / row.frame.detected_people * 100 : 0}%`, background: segment.color }"></i></button></div><div class="state-heatmap-legend"><span v-for="group in timelineGroups" :key="group.id"><i :style="{ background: group.color }"></i>{{ group.label }}</span></div><p class="block-note mono">00:00 <span class="timeline-end">{{ store.durationText }}</span></p></div>

        <div v-if="store.behaviorView === 'overview'" class="behavior-block" data-behavior-panel="overview"><div class="block-title"><h3>{{ hasVisualReference ? '学生整体积极度趋势' : '已检出参与动作比例' }} <span>{{ hasVisualReference ? '原项目规则 · 0.3 / 0.7 连续平滑' : '阅读 · 书写 · 举手 / %' }}</span></h3><small>采样间隔 {{ analysis.sampling_interval_sec }} 秒</small></div><p class="block-note">{{ hasVisualReference ? '七类行为加权并作班级离散修正；低覆盖保留估计。只连接同镜头内连续有效画面，无人物或无有效行为时留空。' : '仅连接同镜头内相邻样本；空白为未知。0% 仅表示未检出上述动作，不等于无人参与。' }}</p>
          <p v-if="hasVisualReference" class="block-note" data-testid="class-engagement-summary">本课平均积极度 <b>{{ classSummary.average === null ? '暂无评分' : `${classSummary.average.toFixed(1)} / 100` }}</b> · 有效评分 {{ classSummary.scored_frames }} / {{ classSummary.total_frames }} 帧 · 按有效画面时长加权</p>
          <div v-if="frames.length" class="participation-chart"><svg viewBox="0 0 920 176" role="img" aria-label="按原录像时间显示的可见参与积极度曲线，空白为未知"><g v-for="tick in [0, 50, 100]" :key="tick"><line x1="44" x2="894" :y1="142 - tick * 1.2" :y2="142 - tick * 1.2" class="chart-grid" /><text x="31" :y="146 - tick * 1.2" text-anchor="end">{{ tick }}</text></g><polyline v-for="(run, i) in curveRuns" :key="i" :points="points(run)" class="participation-line" /><g v-for="frame in curveFrames.filter(f => f.participation_index !== null)" :key="frame.id"><circle :cx="x(frame)" :cy="y(frame)" :r="currentFrame?.id === frame.id ? 4 : 2.4" class="participation-dot"><title>{{ formatReviewTime(frame.timestamp_sec) }} · {{ frame.participation_index }} · 镜头 {{ frame.scene_id }}</title></circle></g><line :x1="44 + store.currentTime / Math.max(1, store.duration) * 850" :x2="44 + store.currentTime / Math.max(1, store.duration) * 850" y1="15" y2="146" class="chart-cursor" /><text x="44" y="168">00:00</text><text x="894" y="168" text-anchor="end">{{ store.durationText }}</text></svg></div>
          <p v-if="!curveRuns.length" class="block-empty">当前没有可计算积极度的状态线索；保留未知。</p>

        </div>

        <details v-if="store.behaviorView === 'overview'" class="student-diagnostics" data-testid="student-diagnostics"><summary>技术诊断与累计观测 <span>采样、规则覆盖与来源</span></summary><p class="block-note">累计次数跨帧重复计数，不代表独立学生人数。可见参与积极度按当前状态规则计算；原始时序分数仍保留在数据中。</p>        <div v-if="store.behaviorView === 'overview'" class="behavior-stats"><div><span>采样帧 / 镜头</span><strong>{{ analysis.summary.sampled_frames }}<small> / {{ analysis.summary.scene_count }}</small></strong></div><div><span>可见对象观测</span><strong>{{ analysis.summary.person_observations }}</strong><small>跨帧累计，非独立人数</small></div><div><span>规则分数覆盖率</span><strong>{{ percentage(summaryCoverage) }}</strong><small>{{ analysis.summary.known_observations }} / {{ analysis.summary.person_observations }} 次观测</small></div></div>          <div class="coverage-timeline" aria-label="规则分数覆盖率与时间定位"><span>规则分数覆盖率</span><div><button v-for="frame in frames" :key="frame.id" :style="{ left: `${frame.start_sec / store.duration * 100}%`, width: `${Math.max(.15, (frame.end_sec - frame.start_sec) / store.duration * 100)}%`, opacity: frame.detected_people && frame.coverage !== null ? .25 + frame.coverage * .75 : 1 }" :class="{ unknown: !frame.detected_people || frame.coverage === null, current: currentFrame?.id === frame.id }" :title="`${formatReviewTime(frame.timestamp_sec)} · 规则分数覆盖率 ${frameCoverage(frame)}`" :aria-label="`定位行为帧 ${frame.id} ${formatReviewTime(frame.timestamp_sec)}`" @click="seekFrame(frame)"></button></div></div><details v-if="currentFrame?.participants.length" class="object-details"><summary>当前对象的来源、姿态依据与置信度</summary><ul><li v-for="participant in currentFrame.participants" :key="participant.track_id"><b>{{ participant.track_id }}</b> · {{ participant.student_state ? studentStateName(participant.student_state.label) : name(participant.label) }}<small v-if="participant.student_state">状态来源 {{ reviewTerm(participant.student_state.source) }} · 置信度 {{ participant.student_state.confidence === null ? '未知' : percentage(participant.student_state.confidence) }} · {{ participant.student_state.evidence.join('；') }}</small><small>原始标签 {{ name(participant.label) }} · 原始置信度 {{ percentage(participant.confidence) }} · 框 {{ participant.bbox.join(', ') }}</small></li></ul></details><p v-if="currentFrame?.participation" class="block-note">可见参与规则权重：{{ Object.entries(currentFrame.participation.weights).map(([key, value]) => `${studentStateName(key)} ${value}`).join(' / ') }}。未知对象排除在规则计算外。</p>        <div v-if="store.behaviorView === 'overview'" class="behavior-block" data-behavior-panel="overview"><div class="block-title"><h3>即时行为标签分布</h3><small>跨采样帧累计的标签观测次数，独立于规则分数可用性</small></div><div v-if="behaviors.length" class="behavior-bars"><div v-for="[label, count] in behaviors" :key="label"><span>{{ name(label) }}</span><div><i :style="{ width: `${count / maxBehavior * 100}%` }"></i></div><b>{{ count }}</b></div></div><p v-else class="block-empty">未提供行为标签计数。</p></div>

</details>

        <div v-if="store.behaviorView === 'heatmap'" class="behavior-block" data-behavior-panel="heatmap"><div class="block-title"><h3>镜头内对象热图</h3><label v-if="scenes.length">镜头 <select :value="sceneId" aria-label="查看镜头内对象" @change="selectedScene = Number(($event.target as HTMLSelectElement).value)"><option v-for="scene in scenes" :key="scene" :value="scene">{{ scene }}</option></select></label></div><p class="block-note">{{ stateHeatmap ? '每格为当前模型状态。跨镜头重新编号，不关联身份；点击格子回看原录像。' : '每格为该可见对象的 0–1 时序动作规则分数。灰色表示未观测或分数未知；跨镜头重新编号，不关联身份。点击格子回看原录像。' }}</p>
          <div v-if="hasVisualReference" class="heatmap-mode" aria-label="热图解释方式"><button :class="{ active: stateHeatmap }" :aria-pressed="stateHeatmap" @click="heatmapMode = 'states'">可见状态</button><button :class="{ active: !stateHeatmap }" :aria-pressed="!stateHeatmap" @click="heatmapMode = 'scores'">时序动作分数</button></div><p v-if="stateHeatmap" class="block-note">读、写、抬、转、举、站、讨表示本帧模型类别；姿表示几何姿态，灰色为未知。颜色区分状态，不表示心理积极度。</p><div v-if="trackRows.length" ref="trackContainer" class="track-scroll"><table class="track-table"><thead><tr><th>可见对象</th><th v-for="frame in heatmapFrames" :key="frame.id" :data-frame-id="frame.id"><button :title="frame.id" @click="seekFrame(frame)">{{ formatReviewTime(frame.timestamp_sec) }}</button></th></tr></thead><tbody><tr v-for="track in trackRows" :key="`${sceneId}-${track.track_id}`"><th>{{ track.track_id }}</th><td v-for="(cell, index) in track.cells" :key="heatmapFrames[index]!.id"><button :style="cellStyle(cell)" :class="{ unknown: !cell || (stateHeatmap ? cellLabel(cell) === 'unknown' : cell.score === null) }" :aria-label="`${track.track_id} ${formatReviewTime(heatmapFrames[index]!.timestamp_sec)} ${cellTitle(cell)}`" :title="cellTitle(cell)" @click="seekFrame(heatmapFrames[index]!)">{{ cellText(cell) }}</button></td></tr></tbody></table></div><p v-else class="block-empty">当前镜头没有可用对象轨迹。</p>
          <div v-if="sceneFrames.length > 100" class="page-controls"><span>当前显示第 {{ heatmapStart + 1 }}–{{ Math.min(heatmapStart + 100, sceneFrames.length) }} / {{ sceneFrames.length }} 帧</span><button class="btn" :disabled="heatmapStart === 0" @click="heatmapStart = Math.max(0, heatmapStart - 100)">上一段</button><button class="btn" :disabled="heatmapStart + 100 >= sceneFrames.length" @click="heatmapStart += 100">下一段</button></div>
        </div>

        <div v-if="store.behaviorView === 'models'" class="behavior-block" data-behavior-panel="models"><div class="block-title"><h3>课堂情境预测</h3><small>分类器概率 · 与行为规则分数分开解释</small></div><p v-if="!currentContexts.length" class="block-empty">此刻没有已训练情境模型的预测记录。</p><div v-for="context in currentContexts" :key="context.id" class="context-card"><button class="context-time mono" @click="store.seek(context.start_sec)">{{ formatReviewTime(context.start_sec) }}–{{ formatReviewTime(context.end_sec) }}</button><p>{{ context.text }}</p><div class="behavior-pills"><span v-for="label in context.labels" :key="label.label">{{ label.name }} <b>{{ percentage(label.probability) }}</b></span></div><small>{{ reviewModelName(context.model_id) }} · {{ reviewTerm(context.method) }} · {{ context.id }}</small></div><details v-if="analysis.context_segments.length" class="context-list"><summary>查看全部 {{ analysis.context_segments.length }} 条情境记录</summary><button v-for="context in analysis.context_segments" :key="context.id" @click="store.seek(context.start_sec)"><span class="mono">{{ formatReviewTime(context.start_sec) }}–{{ formatReviewTime(context.end_sec) }}</span><span>{{ context.text }}</span></button></details></div>

        <div v-if="store.behaviorView === 'frames'" class="behavior-block" data-behavior-panel="frames"><div class="block-title"><h3>原始帧证据</h3><small>点击回到原录像的采样时刻</small></div><div v-if="sourceFrames.length" class="source-grid"><button v-for="frame in sourceFrames" :key="frame.id" class="source-frame" :class="{ selected: frame.id === currentFrame?.id }" @click="seekFrame(frame)"><div class="source-image"><img v-if="frame.image_url && !failedImages.has(frame.id)" :src="frame.image_url" :alt="`原录像 ${formatReviewTime(frame.timestamp_sec)} 镜头 ${frame.scene_id}`" loading="lazy" @error="imageFailed(frame.id)" /><span v-else>原始帧{{ frame.image_url ? '暂不可用' : '未提供' }}</span><span class="source-time mono">{{ formatReviewTime(frame.timestamp_sec) }}</span></div><strong>{{ frame.id }} · 镜头 {{ frame.scene_id }}{{ frame.scene_cut ? '（切换）' : '' }}</strong><small>{{ name(frame.status) }} · 规则分数覆盖率 {{ frameCoverage(frame) }}</small></button></div><p v-else class="block-empty">未提供采样图像或行为帧。</p><div v-if="frames.length > 12" class="page-controls"><span>第 {{ framePage + 1 }} / {{ Math.ceil(frames.length / 12) }} 页</span><button class="btn" :disabled="framePage === 0" @click="framePage--">上一页</button><button class="btn" :disabled="(framePage + 1) * 12 >= frames.length" @click="framePage++">下一页</button></div></div>

        <details v-if="store.behaviorView === 'frames'" class="behavior-evidence"><summary>行为文本证据 · {{ analysis.evidence.length }} 条</summary><button v-for="evidence in analysis.evidence" :key="evidence.id" @click="store.jumpToEvidence(evidence.id)"><span>{{ evidence.id }} · {{ formatReviewTime(evidence.start_sec) }}–{{ formatReviewTime(evidence.end_sec) }}</span><p>{{ evidence.text }}</p></button><p v-if="!analysis.evidence.length">未提供可供问答引用的行为文本。</p></details>
